<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{crearCampana,eliminarCampana,finalizarCampana,guardarFicha,listarCampanas,listarFichas,type Campana,type Ficha,type FichaPayload,type Listado,type Option,type Sector}from'../services/fichas'
const campaigns=ref<Campana[]>([]),districts=ref<Option[]>([]),sectors=ref<Sector[]>([]),criterion=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),createOpen=ref(false),current=ref<Campana|null>(null),sheets=ref<Ficha[]>([]),sheetPage=ref(1),sheetLast=ref(1),sheetTotal=ref(0),sheetLoading=ref(false),editing=ref<Ficha|null>(null),catalogs=reactive({estados:[] as Option[],almacenamientos:[] as Option[],materiales:[] as Option[],tipos_predio:[] as Option[]});const createForm=reactive({nombre:'',distrito_id:0,sector_id:0}),form=reactive<FichaPayload>({estado_predio_id:0,tipo_almacenamiento_id:0,tipo_material_predio_id:0,tipo_predio_id:0});const availableSectors=computed(()=>sectors.value.filter(x=>!createForm.distrito_id||x.distrito_id===createForm.distrito_id));const selectedSector=computed(()=>sectors.value.find(x=>x.id===createForm.sector_id));
async function load(p=1){loading.value=true;page.value=p;try{const r:Listado=await listarCampanas(criterion.value,p);campaigns.value=r.data;districts.value=r.distritos;sectors.value=r.sectores;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=msg(e)}finally{loading.value=false}}function openCreate(){Object.assign(createForm,{nombre:'',distrito_id:0,sector_id:0});createOpen.value=true}async function create(){if(!createForm.nombre.trim()||!createForm.sector_id){error.value='Ingrese el nombre y seleccione el sector de la campaña.';return}if(!confirm(`Se generarán ${selectedSector.value?.predios_count||0} fichas correspondientes a los predios del sector. ¿Continuar?`))return;saving.value=true;try{await crearCampana({nombre:createForm.nombre.trim().toUpperCase(),sector_id:createForm.sector_id});createOpen.value=false;success.value='Campaña creada y fichas generadas correctamente.';await load(1)}catch(e){error.value=msg(e)}finally{saving.value=false}}async function enter(x:Campana,p=1){current.value=x;sheetLoading.value=true;sheetPage.value=p;try{const r=await listarFichas(x.id,p);sheets.value=r.data;sheetLast.value=r.last_page;sheetTotal.value=r.total;Object.assign(catalogs,r.catalogos)}catch(e){error.value=msg(e)}finally{sheetLoading.value=false}}async function finish(x:Campana){if(x.avance<x.predios&&!confirm(`Solo se han completado ${x.avance} de ${x.predios} fichas. ¿Finalizar de todas formas?`))return;try{await finalizarCampana(x.id);success.value='Campaña finalizada correctamente.';await load(page.value)}catch(e){error.value=msg(e)}}async function remove(x:Campana){if(x.avance){error.value='No se puede eliminar una campaña que ya tiene fichas registradas.';return}if(!confirm(`¿Eliminar la campaña ${x.nombre}?`))return;try{await eliminarCampana(x.id);success.value='Campaña eliminada.';await load(page.value)}catch(e){error.value=msg(e)}}function edit(x:Ficha){editing.value=x;Object.assign(form,{estado_predio_id:0,tipo_almacenamiento_id:0,tipo_material_predio_id:0,tipo_predio_id:0})}async function saveSheet(){if(!editing.value||Object.values(form).some(x=>!x)){error.value='Complete los cuatro datos catastrales de la ficha.';return}saving.value=true;try{await guardarFicha(editing.value.id,{...form});editing.value=null;success.value='Ficha registrada correctamente.';if(current.value)await enter(current.value,sheetPage.value)}catch(e){error.value=msg(e)}finally{saving.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Catastro / Fichas</nav><header class="hero"><div class="mark">FC</div><div><small>EVAN · ACTUALIZACIÓN CATASTRAL</small><h1>Campañas y fichas digitales</h1><p>Levantamiento organizado de características de los predios.</p></div><div class="counter"><b>{{total}}</b><span>campañas registradas</span></div><button @click="openCreate">+ Crear campaña</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="search"><input v-model.trim="criterion" placeholder="Buscar campaña" @keyup.enter="load(1)"><button @click="load(1)">Buscar</button></section><div v-if="loading" class="empty">Cargando campañas…</div><div v-else-if="!campaigns.length" class="empty">No se encontraron campañas.</div><section v-else class="cards"><article v-for="x in campaigns" :key="x.id" :class="{done:x.finalizado}"><header><b>{{x.nombre}}</b><span>{{x.finalizado?'FINALIZADA':'EN PROGRESO'}}</span></header><div class="body"><p>{{x.distrito}} · Sector {{x.sector}}</p><div class="progress"><i :style="{width:`${x.predios?x.avance/x.predios*100:0}%`}"></i></div><div class="stats"><span><b>{{x.predios}}</b> predios</span><span><b>{{x.avance}}</b> completadas</span><span><b>{{x.predios?Math.round(x.avance/x.predios*100):0}}%</b> avance</span></div></div><footer><button @click="enter(x)">Ingresar</button><button class="finish" :disabled="x.finalizado" @click="finish(x)">Finalizar</button><button class="delete" :disabled="x.avance>0" @click="remove(x)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="createOpen" class="backdrop" @mousedown.self="createOpen=false"><form class="modal small" @submit.prevent="create"><header><div><small>NUEVA CAMPAÑA</small><h2>Actualización catastral</h2></div><button type="button" @click="createOpen=false">×</button></header><label>Nombre *<input v-model.trim="createForm.nombre"></label><label>Distrito *<select v-model.number="createForm.distrito_id" @change="createForm.sector_id=0"><option :value="0">Seleccione</option><option v-for="x in districts" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Sector *<select v-model.number="createForm.sector_id"><option :value="0">Seleccione</option><option v-for="x in availableSectors" :key="x.id" :value="x.id">{{x.nombre}} ({{x.predios_count}} predios)</option></select></label><footer><button type="button" class="clear" @click="createOpen=false">Cancelar</button><button :disabled="saving">{{saving?'Generando…':'Crear campaña'}}</button></footer></form></div>
<div v-if="current" class="backdrop sheets" @mousedown.self="current=null"><section class="modal wide"><header><div><small>CAMPAÑA</small><h2>{{current.nombre}}</h2><p>{{current.distrito}} · {{sheetTotal}} fichas</p></div><button @click="current=null">×</button></header><div v-if="sheetLoading" class="empty">Cargando fichas…</div><div v-else class="sheet-grid"><article v-for="x in sheets" :key="x.id" :class="{complete:x.finalizado}"><div v-if="x.fotografia_url" class="photo" :style="{backgroundImage:`url(${x.fotografia_url})`}"></div><div class="sheet-body"><b>FICHA # {{x.id}}</b><span>{{x.direccion}}</span><small>Mz. {{x.manzana}} · Lote {{x.lote}} {{x.sublote?`· Sublote ${x.sublote}`:''}}</small><button :disabled="current.finalizado" @click="edit(x)">{{x.finalizado?'Ver / actualizar':'Registrar ficha'}}</button></div></article></div><footer class="pages" v-if="sheetLast>1"><button :disabled="sheetPage<=1" @click="enter(current,sheetPage-1)">Anterior</button><span>{{sheetPage}} / {{sheetLast}}</span><button :disabled="sheetPage>=sheetLast" @click="enter(current,sheetPage+1)">Siguiente</button></footer></section></div>
<div v-if="editing" class="backdrop top" @mousedown.self="editing=null"><form class="modal" @submit.prevent="saveSheet"><header><div><small>FICHA # {{editing.id}}</small><h2>{{editing.direccion}}</h2><p>{{editing.distrito}} · Sector {{editing.sector}} · Mz. {{editing.manzana}} · Lote {{editing.lote}}</p></div><button type="button" @click="editing=null">×</button></header><div class="fields"><label>Estado del predio <small>Actual: {{editing.actual.estado_predio||'SIN DATO'}}</small><select v-model.number="form.estado_predio_id"><option :value="0">Seleccione</option><option v-for="x in catalogs.estados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de almacenamiento <small>Actual: {{editing.actual.tipo_almacenamiento||'SIN DATO'}}</small><select v-model.number="form.tipo_almacenamiento_id"><option :value="0">Seleccione</option><option v-for="x in catalogs.almacenamientos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Material del predio <small>Actual: {{editing.actual.tipo_material||'SIN DATO'}}</small><select v-model.number="form.tipo_material_predio_id"><option :value="0">Seleccione</option><option v-for="x in catalogs.materiales" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de predio <small>Actual: {{editing.actual.tipo_predio||'SIN DATO'}}</small><select v-model.number="form.tipo_predio_id"><option :value="0">Seleccione</option><option v-for="x in catalogs.tipos_predio" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label></div><footer><button type="button" class="clear" @click="editing=null">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar ficha'}}</button></footer></form></div></div></template>
<style scoped>
